namespace RepoContext.Core.Scanning;

/// <summary>
/// A gitignore-style path matcher. Used for <c>.gitignore</c>,
/// <c>.repoctxignore</c>, the config <c>exclude</c> list and
/// <c>sensitiveFiles</c>. Paths are relative to the repository root, use
/// <c>/</c> separators, and directory pruning during traversal handles
/// descendant semantics.
/// </summary>
public sealed class GitignoreMatcher
{
    private readonly record struct Rule(Regex Regex, bool Negate, bool DirOnly, bool Anchored);

    private readonly IReadOnlyList<Rule> _rules;

    private GitignoreMatcher(IReadOnlyList<Rule> rules) => _rules = rules;

    /// <summary>An empty matcher that ignores nothing.</summary>","receipt":"-pisFqj73Or82AqpLy_HeZvXGyidcPfu9_7AnrIr14E"},{"start_line":24,"end_line":69,"symbol":"Parse","text":"    public static GitignoreMatcher Parse(IEnumerable<string> lines)
    {
        var rules = new List<Rule>();
        foreach (string raw in lines)
        {
            string line = raw.TrimEnd();
            if (line.Length == 0 || line.StartsWith('#'))
            {
                continue;
            }

            bool negate = false;
            if (line.StartsWith('!'))
            {
                negate = true;
                line = line[1..];
            }

            bool dirOnly = line.EndsWith('/');
            if (dirOnly)
            {
                line = line[..^1];
            }

            bool anchored = line.StartsWith('/');
            if (anchored)
            {
                line = line[1..];
            }

            // A slash anywhere (other than a trailing one) anchors the pattern.
            if (line.Contains('/'))
            {
                anchored = true;
            }

            if (line.Length == 0)
            {
                continue;
            }

            rules.Add(new Rule(GlobPattern.ToRegex(line), negate, dirOnly, anchored));
        }

        return new GitignoreMatcher(rules);
    }","receipt":"RmMKj7oLvqZNhLxXRtoCKd2LoDSkbpOAHmoZ54hNub0"}]},{"path":"src/RepoContext.Core/Configuration/RepoctxConfig.cs","kind":"source","score":0.3172,"content_tokens":37,"projected_read_tokens":0,"estimated_tokens":154,"file_tokens":1928,"hash":"5f66fff20218","reasons":["fts","symbol:RespectGitignore","symbol:Exclude","imported-by:src/RepoContext.Core/Scanning/FileScanner.cs","mentioned-by:docs/cost-efficiency-implementation-plan.md","imported-by:src/RepoContext.Core/Configuration/Initializer.cs","graph:+63","mentions:repoctx.config.json"],"spans":[{"start_line":25,"end_line":25,"symbol":"Exclude","text":"    public IReadOnlyList<string> Exclude { get; init; } = [];","receipt":"I1UbnUbnPX51N5aofyQeGfnB1tQFWky5kop22NWenXc"},{"start_line":27,"end_line":27,"symbol":"RespectGitignore","text":"    public bool RespectGitignore { get; init; } = true;","receipt":"PIfJ_Xog0MQHmFveZRMYH0S5MLUTlION_RIKCZyap5Y"}]},{"path":"repocontext-produktdoku.md","kind":"doc","score":0.2844,"start_line":127,"end_line":138,"content_tokens":132,"projected_read_tokens":0,"estimated_tokens":296,"file_tokens":3897,"hash":"ca92b73b65ed","receipt":"GeSpm-bPJxb0aqUm2jdLOd_4lDaezET_9C2J_gXJd-o","reasons":["fts","mentions:README.md","mentioned-by:docs/decisions/0017-whole-repository-coverage.md","mentioned-by:docs/build-prompt.md","mentions:repoctx.config.json","mentions:tests/fixtures/sample-cs/Services/UserService.cs","mentions:tests/fixtures/sample-ts/src/auth/__tests__/login.test.ts","mentions:tests/fixtures/sample-ts/src/auth/permissions.ts","mentions:tests/fixtures/sample-ts/src/middleware.ts","mentioned-by:docs/decisions/0003-source-of-truth.md","penalty:doc"],"spans":[{"start_line":127,"end_line":138,"text":"## 7. Tokenverbrauch

