    {
        var pieces = new List<(int Start, string Content)>();
        using (SqliteCommand cmd = _connection.CreateCommand())
        {
            cmd.CommandText =
                "SELECT c.start_line, c.content FROM chunks c JOIN files f ON f.id = c.file_id " +
                "WHERE f.path = $p AND c.kind != 'symbol' AND c.end_line >= $s AND c.start_line <= $e " +
                "ORDER BY c.start_line, c.id";
            cmd.Parameters.AddWithValue("$p", path);
            cmd.Parameters.AddWithValue("$s", startLine);
            cmd.Parameters.AddWithValue("$e", endLine);
            using SqliteDataReader reader = cmd.ExecuteReader();
            while (reader.Read())
            {
                pieces.Add((reader.GetInt32(0), reader.GetString(1)));
            }
        }

        if (pieces.Count == 0)
        {
            return null;
        }

        int firstLine = pieces[0].Start;
        string[] lines = string.Join('\n', pieces.Select(p => p.Content)).Split('\n');
        int from = Math.Max(startLine - firstLine, 0);
        int to = Math.Min(endLine - firstLine, lines.Length - 1);
        if (to < from)
        {
            return null;
        }

        return new SourceSlice(
            string.Join('\n', lines[from..(to + 1)]),
            firstLine + from,
            firstLine + to);
    }","receipt":"ZUB2MmSkAC3byECZDFs_aXUixfrK8JsgMht7QvOwWiA"},{"start_line":899,"end_line":899,"symbol":"Centrality","text":"public readonly record struct Centrality(string Path, int Dependents);","receipt":"6zQQqMe_oL-BifYM0YWd5q0vO-ByJWI2i7TVmbufm8M"}]},{"path":"tests/RepoContext.Core.Tests/Graph/ReferenceExtractorTests.cs","kind":"test","score":0.2789,"content_tokens":813,"projected_read_tokens":0,"estimated_tokens":972,"file_tokens":2244,"hash":"07e713cbd8f8","reasons":["fts","symbol:SourceFiles_ContributeImportsAndTypeUsesRatherThanProseSymbols","symbol:GraphReferences_AreNotSubjectToTheArtifactBound","symbol:File","symbol:ACatastrophicallyBacktrackingPattern_DoesNotAbortTheIndex","imports:src/RepoContext.Core/Parsing/ILanguageParser.cs","test-of:src/RepoContext.Core/Parsing/ILanguageParser.cs","graph:+12","mentions:tests/fixtures/artifact-repo/src/billing/refund.ts","penalty:test"],"spans":[{"start_line":15,"end_line":22,"symbol":"File","text":"    private static ScannedFile File(string path, FileKind kind, SourceLanguage language) => new()
